:root {
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
  --bg-primary: #f8fafc;
  --bg-card: #ffffff;
  --bg-hover: #f1f5f9;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --border-focus: #6366f1;
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.08);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* App Container */
.kanban-app {
  max-width: 1400px;
  margin: 0 auto;
  padding: 24px 20px 48px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Header & Toolbar */
.kanban-header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 28px;
}

@media (min-width: 768px) {
  .kanban-header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.kanban-header-left {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.kanban-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #1e293b;
}

.kanban-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.kanban-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.search-container {
  display: flex;
  align-items: center;
  gap: 8px;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 8px 14px;
  color: var(--text-muted);
  box-shadow: var(--shadow-sm);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  min-width: 240px;
  flex: 1;
}

.search-container:focus-within {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15);
}

.search-input {
  border: none;
  background: transparent;
  outline: none;
  color: var(--text-main);
  font-size: 0.875rem;
  width: 100%;
}

.search-input::placeholder {
  color: #94a3b8;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 0.875rem;
  font-weight: 500;
  padding: 8px 16px;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
  box-shadow: 0 1px 3px rgba(79, 70, 229, 0.3);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: #ffffff;
  color: var(--text-main);
  border-color: var(--border-color);
}

.btn-secondary:hover {
  background-color: var(--bg-hover);
}

.icon-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 6px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s ease, background-color 0.15s ease;
}

.icon-btn:hover {
  color: var(--text-main);
  background-color: var(--bg-hover);
}

/* Kanban Board Layout */
.kanban-board {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  align-items: start;
}

@media (min-width: 768px) {
  .kanban-board {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Column */
.kanban-column {
  background-color: #f1f5f9;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 160px);
  overflow: hidden;
}

.kanban-column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 16px 12px;
  border-bottom: 1px solid #e2e8f0;
  background-color: #ffffff;
}

.column-title-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.column-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.column-title-group h3 {
  font-size: 0.95rem;
  font-weight: 600;
  color: #1e293b;
}

.column-badge {
  font-size: 0.75rem;
  font-weight: 600;
  background-color: #e2e8f0;
  color: #475569;
  padding: 2px 8px;
  border-radius: 999px;
}

.kanban-column-body {
  padding: 14px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 160px;
  transition: background-color 0.2s ease, border-color 0.2s ease;
}

.column-drag-over {
  background-color: #e0e7ff;
  border: 2px dashed #6366f1;
}

.column-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 120px;
  color: #94a3b8;
  font-size: 0.85rem;
  border: 1px dashed #cbd5e1;
  border-radius: var(--radius-md);
  background-color: rgba(255, 255, 255, 0.5);
}

/* Task Card */
.task-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 14px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 10px;
  cursor: grab;
  user-select: none;
  transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;
}

.task-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.task-card:active {
  cursor: grabbing;
}

.task-card-dragging {
  opacity: 0.4;
  border-style: dashed;
  border-color: #6366f1;
}

.task-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.task-grip {
  color: #94a3b8;
  cursor: grab;
  display: inline-flex;
  align-items: center;
}

.task-card-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.quick-status-btn {
  font-size: 0.725rem;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background-color: var(--bg-hover);
  color: var(--text-muted);
  cursor: pointer;
  outline: none;
}

.quick-status-btn:focus {
  border-color: var(--border-focus);
}

/* Priority Badges */
.priority-badge {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  border: 1px solid transparent;
  line-height: 1.4;
}

.priority-high {
  background-color: #fee2e2;
  color: #b91c1c;
  border-color: #fca5a5;
}

.priority-medium {
  background-color: #fef3c7;
  color: #b45309;
  border-color: #fcd34d;
}

.priority-low {
  background-color: #ecfdf5;
  color: #047857;
  border-color: #a7f3d0;
}

/* Task Content */
.task-card-title {
  font-size: 0.925rem;
  font-weight: 600;
  color: #1e293b;
  line-height: 1.4;
  word-break: break-word;
}

.task-card-desc {
  font-size: 0.825rem;
  color: var(--text-muted);
  line-height: 1.5;
  word-break: break-word;
  white-space: pre-wrap;
}

.task-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 6px;
  border-top: 1px solid #f1f5f9;
  font-size: 0.75rem;
}

.task-tag {
  background-color: #eef2ff;
  color: #4338ca;
  padding: 2px 8px;
  border-radius: 4px;
  font-weight: 500;
  max-width: 130px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.task-date {
  color: #94a3b8;
  margin-left: auto;
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(15, 23, 42, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 1000;
  backdrop-filter: blur(2px);
}

.modal-content {
  background-color: #ffffff;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: modal-enter 0.18s ease-out;
}

@keyframes modal-enter {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  border-bottom: 1px solid var(--border-color);
}

.modal-header h2 {
  font-size: 1.15rem;
  font-weight: 600;
  color: #1e293b;
}

.modal-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow-y: auto;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.form-row {
  display: flex;
  gap: 12px;
}

.form-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: #334155;
}

.form-input,
.form-textarea,
.form-select {
  width: 100%;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 9px 12px;
  font-size: 0.875rem;
  color: var(--text-main);
  background-color: #ffffff;
  outline: none;
  font-family: inherit;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.form-input:focus,
.form-textarea:focus,
.form-select:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15);
}

.form-textarea {
  resize: vertical;
  min-height: 80px;
}

.modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 20px;
  border-top: 1px solid var(--border-color);
  background-color: #f8fafc;
}

import type { DragEvent } from 'react';

export type TaskStatus = 'todo' | 'in_progress' | 'done';

export type Priority = 'low' | 'medium' | 'high';

export interface KanbanTask {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: Priority;
  createdAt: string;
  tag: string;
  dueDate?: string;
  order?: number;
}

export interface TaskFormData {
  id?: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: Priority;
  tag: string;
  dueDate?: string;
}

export interface ColumnDef {
  id: TaskStatus;
  title: string;
  color: string;
}

export interface TaskCardProps {
  task: KanbanTask;
  onDragStart?: (e: DragEvent, id: string) => void;
  onEdit?: (task: KanbanTask) => void;
  onDelete?: (id: string) => void;
  onStatusChange?: (id: string, newStatus: TaskStatus) => void;
}

export interface KanbanColumnProps {
  column: ColumnDef;
  tasks?: KanbanTask[];
  onDragStart?: (e: DragEvent, id: string) => void;
  onDragOver?: (e: DragEvent) => void;
  onDrop?: (e: DragEvent, status: TaskStatus) => void;
  onEditTask?: (task: KanbanTask) => void;
  onDeleteTask?: (id: string) => void;
  onStatusChange?: (id: string, newStatus: TaskStatus) => void;
  onQuickAddTask?: (status: TaskStatus) => void;
}

import type { DragEvent, ChangeEvent } from 'react';
import { useState } from 'react';
import { GripVertical, Edit2, Trash2 } from 'lucide-react';
import type { Priority, TaskCardProps, TaskStatus } from '../types';

const priorityLabels: Record<Priority, string> = {
  high: '高',
  medium: '中',
  low: '低',
};

const priorityClasses: Record<Priority, string> = {
  high: 'priority-high',
  medium: 'priority-medium',
  low: 'priority-low',
};

const TaskCard = ({
  task,
  onDragStart,
  onEdit,
  onDelete,
  onStatusChange,
}: TaskCardProps) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragStart = (e: DragEvent<HTMLDivElement>) => {
    setIsDragging(true);
    e.dataTransfer.setData('text/plain', task.id);
    onDragStart?.(e, task.id);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const handleStatusSelect = (e: ChangeEvent<HTMLSelectElement>) => {
    const nextStatus = e.target.value as TaskStatus;
    onStatusChange?.(task.id, nextStatus);
  };

  const handleDelete = () => {
    if (window.confirm(`タスク「${task.title}」を削除してもよろしいですか？`)) {
      onDelete?.(task.id);
    }
  };

  const priorityClass = priorityClasses[task.priority] || 'priority-medium';
  const cardClassName = isDragging ? 'task-card task-card-dragging' : 'task-card';

  return (
    <div
      className={cardClassName}
      draggable
      role="article"
      tabIndex={0}
      aria-label={`タスク: ${task.title}`}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className="task-card-header">
        <span className="task-grip" title="ドラッグして移動" aria-hidden="true">
          <GripVertical size={16} />
        </span>
        <span className={`priority-badge ${priorityClass}`}>
          {priorityLabels[task.priority] ?? task.priority}
        </span>
        <div className="task-card-actions">
          <select
            className="quick-status-btn"
            value={task.status}
            onChange={handleStatusSelect}
            aria-label="ステータス変更"
            title="移動先を変更"
          >
            <option value="todo">未着手</option>
            <option value="in_progress">作業中</option>
            <option value="done">完了</option>
          </select>
          <button
            type="button"
            className="icon-btn"
            onClick={() => onEdit?.(task)}
            title="タスクを編集"
            aria-label="タスクを編集"
          >
            <Edit2 size={14} />
          </button>
          <button
            type="button"
            className="icon-btn"
            onClick={handleDelete}
            title="タスクを削除"
            aria-label="タスクを削除"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      <div className="task-card-title">{task.title}</div>
      {task.description && (
        <div className="task-card-desc">{task.description}</div>
      )}

      <div className="task-card-footer">
        {task.tag && <span className="task-tag">{task.tag}</span>}
        <span className="task-date">{task.createdAt}</span>
      </div>
    </div>
  );
};

export default TaskCard;

import type { DragEvent } from 'react';
import { useState } from 'react';
import { Plus } from 'lucide-react';
import type { KanbanColumnProps } from '../types';
import TaskCard from './TaskCard';

const KanbanColumn = ({
  column,
  tasks = [],
  onDragStart,
  onDragOver,
  onDrop,
  onEditTask,
  onDeleteTask,
  onStatusChange,
  onQuickAddTask,
}: KanbanColumnProps) => {
  const [isDragOver, setIsDragOver] = useState(false);

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragOver(true);
    onDragOver?.(e);
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    if (e.currentTarget.contains(e.relatedTarget as Node)) {
      return;
    }
    setIsDragOver(false);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragOver(false);
    onDrop?.(e, column.id);
  };

  const columnBodyClass = isDragOver
    ? 'kanban-column-body column-drag-over'
    : 'kanban-column-body';

  return (
    <section
      className="kanban-column"
      aria-label={`${column.title}カラム`}
    >
      <div className="kanban-column-header">
        <div className="column-title-group">
          <span
            className="column-dot"
            style={{ backgroundColor: column.color }}
            aria-hidden="true"
          />
          <h3>{column.title}</h3>
          <span className="column-badge" aria-label={`タスク数: ${tasks.length}`}>
            {tasks.length}
          </span>
        </div>
        <button
          type="button"
          className="icon-btn"
          onClick={() => onQuickAddTask?.(column.id)}
          title={`${column.title}にタスクを追加`}
          aria-label={`${column.title}にタスクを追加`}
        >
          <Plus size={18} />
        </button>
      </div>

      <div
        className={columnBodyClass}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        role="region"
        aria-label={`${column.title}のタスク一覧`}
      >
        {tasks.length === 0 ? (
          <div className="column-empty">
            タスクがありません（ドラッグ＆ドロップで追加）
          </div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onDragStart}
              onEdit={onEditTask}
              onDelete={onDeleteTask}
              onStatusChange={onStatusChange}
            />
          ))
        )}
      </div>
    </section>
  );
};

export default KanbanColumn;

