const generateTaskId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `task-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
};

const App = () => {
  const [tasks, setTasks] = useState<KanbanTask[]>(INITIAL_TASKS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<TaskFormData>(defaultFormData);
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);

  useEffect(() => {
    if (!isModalOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsModalOpen(false);
        setFormData(defaultFormData);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isModalOpen]);

  const filteredTasks = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return tasks;
    return tasks.filter(
      (task) =>
        task.title.toLowerCase().includes(q) ||
        task.description.toLowerCase().includes(q) ||
        task.tag.toLowerCase().includes(q)
    );
  }, [tasks, searchQuery]);

  const handleOpenCreateModal = (initialStatus: TaskStatus = 'todo') => {
    setFormData({
      ...defaultFormData,
      status: initialStatus,
    });
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (task: KanbanTask) => {
    setFormData({
      id: task.id,
      title: task.title,
      description: task.description,
      status: task.status,
      priority: task.priority,
      tag: task.tag,
    });
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setFormData(defaultFormData);
  };

  const handleSubmitModal = (e: FormEvent) => {
    e.preventDefault();
    if (!formData.title.trim()) return;

    if (formData.id) {
      // 編集更新
      setTasks((prev) =>
        prev.map((t) =>
          t.id === formData.id
            ? {
                ...t,
                title: formData.title.trim(),
                description: formData.description.trim(),
                status: formData.status,
                priority: formData.priority,
                tag: formData.tag.trim(),
              }
            : t
        )
      );
    } else {
      // 新規作成
      const now = new Date();
      const dateStr = `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')}`;
      const newTask: KanbanTask = {
        id: generateTaskId(),
        title: formData.title.trim(),
        description: formData.description.trim(),
        status: formData.status,
        priority: formData.priority,
        createdAt: dateStr,
        tag: formData.tag.trim(),
      };
      setTasks((prev) => [newTask, ...prev]);
    }

    handleCloseModal();
  };

  const handleDeleteTask = (id: string) => {
    setTasks((prev) => prev.filter((t) => t.id !== id));
  };

  const handleStatusChange = (id: string, newStatus: TaskStatus) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, status: newStatus } : t))
    );
  };

  const handleDragStart = (_e: DragEvent, id: string) => {
    setDraggedTaskId(id);
  };

  const handleDragOver = (e: DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: DragEvent, newStatus: TaskStatus) => {
    e.preventDefault();
    const taskId = draggedTaskId || e.dataTransfer.getData('text/plain');
    if (taskId) {
      handleStatusChange(taskId, newStatus);
    }
    setDraggedTaskId(null);
  };

  return (
    <div className="kanban-app">
      <header className="kanban-header">
        <div className="kanban-header-left">
          <h1 className="kanban-title">カンバンボード</h1>
          <p className="kanban-subtitle">
            タスクを視覚的に整理し、ドラッグ＆ドロップで進行状況を更新できます
          </p>
        </div>

        <div className="kanban-toolbar">
          <div className="search-container">
            <Search size={16} />
            <input
              type="text"
              className="search-input"
              placeholder="タイトル・説明・タグで検索..."
              value={searchQuery}
              onChange={(e: ChangeEvent<HTMLInputElement>) =>
                setSearchQuery(e.target.value)
              }
            />
          </div>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => handleOpenCreateModal('todo')}
          >
            <Plus size={16} />
            <span>タスク追加</span>
          </button>
        </div>
      </header>

      <main className="kanban-board">
        {COLUMNS.map((col) => {
          const colTasks = filteredTasks.filter((t) => t.status === col.id);
          return (
            <KanbanColumn
              key={col.id}
              column={col}
              tasks={colTasks}
              onDragStart={handleDragStart}
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onEditTask={handleOpenEditModal}
              onDeleteTask={handleDeleteTask}
              onStatusChange={handleStatusChange}
              onQuickAddTask={handleOpenCreateModal}
            />
          );
        })}
      </main>

      {isModalOpen && (
        <div className="modal-backdrop" onClick={handleCloseModal}>
          <div
            className="modal-content"
            onClick={(e) => e.stopPropagation()}
            role="dialog"
            aria-modal="true"
            aria-labelledby="modal-title"
          >
            <div className="modal-header">
              <h2 id="modal-title">
                {formData.id ? 'タスクの編集' : '新規タスクの作成'}
              </h2>
              <button
                type="button"
                className="icon-btn"
                onClick={handleCloseModal}
                aria-label="閉じる"
              >
                <X size={18} />
              </button>
            </div>

            <form onSubmit={handleSubmitModal}>
              <div className="modal-body">
                <div className="form-group">
                  <label className="form-label">
                    タスク名 <span style={{ color: '#ef4444' }}>*</span>
                  </label>
                  <input
                    type="text"
                    required
                    className="form-input"
                    placeholder="例: API仕様書の作成"
                    value={formData.title}
                    onChange={(e: ChangeEvent<HTMLInputElement>) =>
                      setFormData((prev) => ({ ...prev, title: e.target.value }))
                    }
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">説明</label>
                  <textarea
                    rows={3}
                    className="form-textarea"
                    placeholder="タスクの具体的な内容や手順を入力"
                    value={formData.description}
                    onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
                      setFormData((prev) => ({
                        ...prev,
                        description: e.target.value,
                      }))
                    }
                  />
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">ステータス</label>
                    <select
                      className="form-select"
                      value={formData.status}
                      onChange={(e: ChangeEvent<HTMLSelectElement>) =>
                        setFormData((prev) => ({
                          ...prev,
                          status: e.target.value as TaskStatus,
                        }))
                      }
                    >
                      <option value="todo">未着手</option>
                      <option value="in_progress">作業中</option>
                      <option value="done">完了</option>
                    </select>
                  </div>

                  <div className="form-group">
                    <label className="form-label">優先度</label>
                    <select
                      className="form-select"
                      value={formData.priority}
                      onChange={(e: ChangeEvent<HTMLSelectElement>) =>
                        setFormData((prev) => ({
                          ...prev,
                          priority: e.target.value as Priority,
                        }))
                      }
                    >
                      <option value="low">低</option>
                      <option value="medium">中</option>
                      <option value="high">高</option>
                    </select>
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">タグ</label>
                  <input
                    type="text"
                    className="form-input"
                    placeholder="例: フロントエンド, 設計"
                    value={formData.tag}
                    onChange={(e: ChangeEvent<HTMLInputElement>) =>
                      setFormData((prev) => ({ ...prev, tag: e.target.value }))
                    }
                  />
                </div>
              </div>

              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleCloseModal}
                >
                  キャンセル
                </button>
                <button type="submit" className="btn btn-primary">
                  {formData.id ? '変更を保存' : '作成する'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
